\section{Introduction}

A positional numeral system expresses a natural number as a weighted sum of
\emph{digits}, where the weights are prescribed \emph{place values}. In base $N$
the place values are $1, N, N^2, \dots$ and each digit lies in
$\{0,\dots,N-1\}$. The \emph{factorial number system} (factoradic) replaces the
powers by the factorials $1,1,2,6,24,\dots$ and lets the digit in place $i$
range over $\{0,\dots,i\}$. The factoradic system is the natural coordinate
system for permutations: it underlies the Lehmer code and the standard
ranking/unranking algorithms.

Base $N$ obeys one fixed rule; the factorial system changes its rule at every
place. We show they are not different constructions: both are instances of a
single \emph{mixed-radix} theory, and the properties one wants---unique and
complete representation---hold for the whole family under one proof. A guiding
principle is \emph{non-circularity}: the re-derivation of the factoradic result
depends on the general theorem and the bridge identities, not on the classical
factoradic proof.

\section{Definitions}

Throughout, $b : \mathbb{N} \to \mathbb{N}$ is a sequence of \emph{bases} and
$c, d : \mathbb{N} \to \mathbb{N}$ are \emph{digit functions}.

\begin{definition}[Running product / place value]
The place value of position $i$ is
\[
  P_i := \radixprod(b, i) = \prod_{j=0}^{i-1} b_j, \qquad P_0 = 1,
\]
satisfying $P_{i+1} = P_i \cdot b_i$.
\end{definition}

\begin{definition}[Mixed-radix value]
The length-$k$ value of $c$ under bases $b$ is
\[
  \val(b, c, k) = \sum_{i=0}^{k-1} c_i\, P_i = \sum_{i=0}^{k-1} c_i \prod_{j<i} b_j,
\]
satisfying $\val(b,c,k+1) = \val(b,c,k) + c_k\, P_k$.
\end{definition}

\begin{definition}[Validity]
$\Valid(b,c,k) :\iff \forall\, i < k,\ c_i < b_i.$
\end{definition}

\begin{definition}[Factorial number system]
$\val_{\mathrm{F}}(c,k) = \sum_{i=0}^{k-1} c_i\, i!$ and
$\Valid_{\mathrm{F}}(c,k) :\iff \forall\, i<k,\ c_i \le i.$
\end{definition}

\noindent\textbf{Special cases.} Base $N$: $b_i = N$, so $P_i = N^i$ and
validity is $c_i < N$. Factorial: $b_i = i+1$, so $P_i = i!$ and validity is
$c_i \le i$.

\section{The mixed-radix uniqueness theory}

All results hold for an arbitrary base sequence $b$; the development uses only
the digit-bound estimate and Euclidean splitting, avoiding cardinality,
surjectivity, or bijection arguments.

\begin{lemma}[Positivity of place values under validity]
If $\Valid(b,c,k+1)$ then $P_k > 0$.
\end{lemma}
\begin{proof}[Proof sketch]
Each factor $b_i$ with $i<k$ satisfies $b_i > c_i \ge 0$, hence $b_i \ge 1$; a
product of positive naturals is positive.
\end{proof}

\begin{lemma}[Digit-bound estimate]\label{lem:bound}
If $\Valid(b,c,k)$ then $\val(b,c,k) < P_k = \prod_{i<k} b_i$.
\end{lemma}
\begin{proof}[Proof sketch]
Induct on $k$. The step uses
\[
  \val(b,c,k+1) = \val(b,c,k) + c_k P_k < P_k + c_k P_k = (1+c_k)P_k \le b_k P_k = P_{k+1},
\]
by the inductive bound on the tail and $c_k < b_k$.
\end{proof}

\begin{lemma}[Euclidean splitting]\label{lem:split}
If $\Valid(b,c,k+1)$ then
\[
  \left\lfloor \frac{\val(b,c,k+1)}{P_k} \right\rfloor = c_k,
  \qquad
  \val(b,c,k+1) \bmod P_k = \val(b,c,k).
\]
\end{lemma}
\begin{proof}[Proof sketch]
Write $\val(b,c,k+1) = \val(b,c,k) + c_k P_k$. By Lemma~\ref{lem:bound} the tail
is below $P_k$, so it is the remainder and $c_k$ the quotient.
\end{proof}

\begin{theorem}[Uniqueness of mixed-radix representations]\label{thm:unique}
If $\Valid(b,c,k)$, $\Valid(b,d,k)$, and $\val(b,c,k) = \val(b,d,k)$, then
$c_i = d_i$ for all $i < k$.
\end{theorem}
\begin{proof}[Proof sketch]
Induct on $k$. Dividing both equal values by $P_k$ (Lemma~\ref{lem:split})
forces $c_k = d_k$; reducing mod $P_k$ reduces to equal tails, to which the
induction hypothesis applies.
\end{proof}

\begin{definition}[Digit extraction]
$\displaystyle \digit(b, n, i) = \left\lfloor \frac{n}{P_i} \right\rfloor \bmod b_i.$
\end{definition}

\begin{theorem}[Existence / surjectivity]\label{thm:exist}
For every $n < P_k$, $\val\bigl(b,\ \digit(b,n,\cdot),\ k\bigr) = n$; and when
every base is positive, the extracted digits are valid.
\end{theorem}
\begin{proof}[Proof sketch]
By induction on $m$,
$n = \sum_{i<m}\bigl(\lfloor n/P_i\rfloor \bmod b_i\bigr)P_i + \lfloor n/P_m\rfloor P_m$,
using $P_{i+1}=P_i b_i$. At $m=k$ the trailing term vanishes since $n<P_k$.
Validity holds since a remainder mod $b_i$ is below $b_i$.
\end{proof}

\begin{corollary}[Perfect dictionary]
For fixed $k$ and positive bases, $c \mapsto \val(b,c,k)$ is a bijection between
valid length-$k$ digit strings and $\{0,\dots,P_k-1\}$.
\end{corollary}

\section{The bridge to the factorial system}

\begin{lemma}[Place values are factorials]\label{lem:fact}
$\radixprod\bigl((i\mapsto i+1),\ k\bigr) = \prod_{j<k}(j+1) = k!.$
\end{lemma}
\begin{proof}[Proof sketch]
Induction: $P_{k+1} = P_k(k+1) = k!(k+1) = (k+1)!$.
\end{proof}

\begin{theorem}[Value agreement]\label{thm:val}
$\val\bigl((i\mapsto i+1),\ c,\ k\bigr) = \val_{\mathrm{F}}(c,k).$
\end{theorem}
\begin{proof}[Proof sketch]
Both are sums over $\{0,\dots,k-1\}$ and agree term-by-term since $P_i = i!$ by
Lemma~\ref{lem:fact}.
\end{proof}

\begin{theorem}[Validity agreement]\label{thm:valid}
$\Valid\bigl((i\mapsto i+1),\ c,\ k\bigr) \iff \Valid_{\mathrm{F}}(c,k).$
\end{theorem}
\begin{proof}[Proof sketch]
Position-wise, $c_i < i+1 \iff c_i \le i$ for naturals.
\end{proof}

\begin{theorem}[Factoradic uniqueness, re-derived]\label{thm:factunique}
If $\Valid_{\mathrm{F}}(c,k)$, $\Valid_{\mathrm{F}}(d,k)$, and
$\val_{\mathrm{F}}(c,k) = \val_{\mathrm{F}}(d,k)$, then $c_i = d_i$ for all
$i<k$.
\end{theorem}
\begin{proof}[Proof sketch]
Transport the hypotheses to mixed-radix form via Theorems~\ref{thm:val} and
\ref{thm:valid}, then apply Theorem~\ref{thm:unique} at $b_i = i+1$.
\end{proof}

\begin{remark}[Non-circularity]
Theorem~\ref{thm:factunique} uses only Theorem~\ref{thm:unique} and the bridge
identities~\ref{thm:val},~\ref{thm:valid}, none of which depend on any
special-case factoradic argument. The generalization contains the classical
result rather than restating it.
\end{remark}

\begin{remark}[Base $N$ as a second instance]
Taking $b_i = N$ gives $P_i = N^i$, and Theorem~\ref{thm:unique} specializes to
uniqueness of ordinary base-$N$ numerals.
\end{remark}

\section{Algorithms}

\noindent\textbf{Encoding.} Given $n,k$: for $i=0,\dots,k-1$ set
$c_i = \lfloor n/P\rfloor \bmod b_i$ and update $P \leftarrow P\, b_i$; complexity
$O(k)$ big-integer operations.

\noindent\textbf{Decoding.} Accumulate $\val = \sum_i c_i P_i$ with the same
running product $P$.

\noindent\textbf{Ranking permutations.} For $\pi$ of $\{0,\dots,k-1\}$, the
Lehmer code $L_i(\pi) = \#\{j>i : \pi_j < \pi_i\}$ satisfies $0 \le L_i \le
k-1-i$; reading it as factoradic digits yields the lexicographic rank.
Uniqueness (Theorem~\ref{thm:factunique}) makes ranks distinct; existence
(Theorem~\ref{thm:exist}) makes every $0 \le r < k!$ a permutation.

\section{Applications and discussion}

Mixed-radix systems model constant-time permutation unranking, odometers and
mixed-unit counters (time, calendars), and dense tuple encodings for
differently sized alphabets. The structural payoff is that one proof certifies
an entire family of numeral systems. The digit-bound estimate
(Lemma~\ref{lem:bound}) is the linchpin, powering both uniqueness and existence,
and never mentioning a specific base.

\section{Future work}

A base-$N$ bridge re-deriving ordinary base-$N$ uniqueness as a second explicit
instance; transport of the existence/extraction results between the factorial
and mixed-radix systems; and variable-length or infinite representations with
canonical-form results.

\section{Conclusion}

The factorial number system is an instance of ordinary positional arithmetic,
not an exception to it. Parameterizing over an arbitrary base sequence and
proving uniqueness and existence once yields the factoradic theory and base $N$
as corollaries. Place values are running products of the bases, digits stay
below their bases, and from that single law the defining virtue of any
notation---naming each number exactly once---follows automatically.

